import React, { useState } from 'react';
import { useForm } from 'react-hook-form';
import { customerService } from '../services/api';
import { CustomerRequest, CustomerResponse } from '../types';
import { X } from 'lucide-react';

type CustomerFormData = {
  firstName: string;
  lastName: string;
  email: string;
  phone?: string;
  company?: string;
  notes?: string;
};

interface CustomerFormProps {
  customer?: CustomerResponse | null;
  onClose: () => void;
}

const CustomerForm: React.FC<CustomerFormProps> = ({ customer, onClose }) => {
  const [error, setError] = useState<string>('');
  const [isLoading, setIsLoading] = useState(false);

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<CustomerFormData>({
    defaultValues: customer ? {
      firstName: customer.firstName,
      lastName: customer.lastName,
      email: customer.email,
      phone: customer.phone || '',
      company: customer.company || '',
      notes: customer.notes || '',
    } : undefined,
  });

  const onSubmit = async (data: CustomerFormData) => {
    setIsLoading(true);
    setError('');

    try {
      const customerData: CustomerRequest = {
        firstName: data.firstName,
        lastName: data.lastName,
        email: data.email,
        phone: data.phone || undefined,
        company: data.company || undefined,
        notes: data.notes || undefined,
      };

      if (customer) {
        await customerService.updateCustomer(customer.id, customerData);
      } else {
        await customerService.createCustomer(customerData);
      }
      onClose();
    } catch (err: any) {
      setError(err.response?.data?.message || 'Failed to save customer');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="container">
      <div className="card">
        <div className="d-flex justify-content-between align-items-center mb-4">
          <h2>{customer ? 'Edit Customer' : 'Add New Customer'}</h2>
          <button
            className="btn btn-secondary"
            onClick={onClose}
            title="Close"
          >
            <X size={20} />
          </button>
        </div>

        {error && (
          <div className="alert alert-error">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit(onSubmit)}>
          <div className="d-flex gap-3">
            <div className="form-group" style={{ flex: 1 }}>
              <label className="form-label">First Name *</label>
              <input
                type="text"
                className="form-input"
                {...register('firstName')}
                placeholder="Enter first name"
              />
              {errors.firstName && (
                <div className="form-error">{errors.firstName.message}</div>
              )}
            </div>

            <div className="form-group" style={{ flex: 1 }}>
              <label className="form-label">Last Name *</label>
              <input
                type="text"
                className="form-input"
                {...register('lastName')}
                placeholder="Enter last name"
              />
              {errors.lastName && (
                <div className="form-error">{errors.lastName.message}</div>
              )}
            </div>
          </div>

          <div className="form-group">
            <label className="form-label">Email *</label>
            <input
              type="email"
              className="form-input"
              {...register('email')}
              placeholder="Enter email address"
            />
            {errors.email && (
              <div className="form-error">{errors.email.message}</div>
            )}
          </div>

          <div className="d-flex gap-3">
            <div className="form-group" style={{ flex: 1 }}>
              <label className="form-label">Phone</label>
              <input
                type="tel"
                className="form-input"
                {...register('phone')}
                placeholder="Enter phone number"
              />
              {errors.phone && (
                <div className="form-error">{errors.phone.message}</div>
              )}
            </div>

            <div className="form-group" style={{ flex: 1 }}>
              <label className="form-label">Company</label>
              <input
                type="text"
                className="form-input"
                {...register('company')}
                placeholder="Enter company name"
              />
              {errors.company && (
                <div className="form-error">{errors.company.message}</div>
              )}
            </div>
          </div>

          <div className="form-group">
            <label className="form-label">Notes</label>
            <textarea
              className="form-input"
              rows={4}
              {...register('notes')}
              placeholder="Enter additional notes"
            />
            {errors.notes && (
              <div className="form-error">{errors.notes.message}</div>
            )}
          </div>

          <div className="d-flex gap-2 justify-content-between">
            <button
              type="button"
              className="btn btn-secondary"
              onClick={onClose}
            >
              Cancel
            </button>
            <button
              type="submit"
              className="btn btn-primary"
              disabled={isLoading}
            >
              {isLoading ? 'Saving...' : (customer ? 'Update Customer' : 'Create Customer')}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default CustomerForm;
